package local.pitv;
import java.io.*;import java.net.*;import java.util.*;
/** Playback-owned loopback relay. Copies video; repairs only gross audio PTS offsets. */
final class TsAudioRepair implements AutoCloseable {
 static final long MASK=(1L<<33)-1,WRAP=1L<<33;final ServerSocket server;final String token=UUID.randomUUID().toString();volatile boolean closed;volatile Socket client;volatile InputStream upstream;volatile HttpURLConnection connection;volatile long packets,adjusted;volatile String state="Waiting";final String source;
 TsAudioRepair(String address)throws IOException{source=address;server=new ServerSocket(0,1,InetAddress.getByName("127.0.0.1"));Thread t=new Thread(this::serve,"PiTV-audio-relay");t.setDaemon(true);t.start();}
 String url(){return "http://127.0.0.1:"+server.getLocalPort()+"/"+token+".ts";}
 void serve(){try{while(!closed){client=server.accept();client.setSoTimeout(8000);BufferedReader header=new BufferedReader(new InputStreamReader(client.getInputStream(),"US-ASCII"));String request=header.readLine();String line;while((line=header.readLine())!=null&&!line.isEmpty()){}if(request==null||!request.startsWith("GET /"+token+".ts ")){client.close();continue;}URI uri=URI.create(source);if("file".equals(uri.getScheme()))upstream=new FileInputStream(new File(uri));else{String target=source.replaceFirst("\\.m3u8(?=\\?|$)",".ts");connection=(HttpURLConnection)new URL(target).openConnection();connection.setConnectTimeout(8000);connection.setReadTimeout(12000);connection.setRequestProperty("User-Agent","PiTV/0.4");int status=connection.getResponseCode();if(status!=200)throw new IOException("Source status");upstream=connection.getInputStream();}upstream=new BufferedInputStream(upstream,65536);OutputStream out=new BufferedOutputStream(client.getOutputStream(),188*128);out.write("HTTP/1.1 200 OK\r\nContent-Type: video/mp2t\r\nConnection: close\r\nCache-Control: no-store\r\n\r\n".getBytes("US-ASCII"));out.flush();state="Repairing audio timing";Retimer retimer=new Retimer();byte[] packet=new byte[188];while(!closed&&readPacket(upstream,packet)){if(retimer.rewrite(packet))adjusted++;out.write(packet);if(++packets%64==0)out.flush();}out.flush();break;}}catch(Exception e){if(!closed)state="Source or relay ended";}finally{close();}}
 static boolean readPacket(InputStream in,byte[] p)throws IOException{int first=in.read(),skipped=0;while(first>=0&&first!=0x47){if(++skipped>8192)throw new IOException("Not a transport stream");first=in.read();}if(first<0)return false;p[0]=0x47;int n=1;while(n<188){int r=in.read(p,n,188-n);if(r<0)return false;n+=r;}return true;}
 public void close(){closed=true;try{server.close();}catch(Exception ignored){}try{if(upstream!=null)upstream.close();}catch(Exception ignored){}try{if(client!=null)client.close();}catch(Exception ignored){}if(connection!=null)connection.disconnect();}
 static final class Retimer {
  long video=-1;final Map<Integer,Long> offsets=new HashMap<>();
  boolean rewrite(byte[] p){if(p.length!=188||(p[0]&255)!=0x47||(p[1]&0x80)!=0||(p[1]&0x40)==0)return false;int af=(p[3]>>4)&3;if(af==0||af==2)return false;int at=4;if(af==3)at+=1+(p[4]&255);if(at+14>188||p[at]!=0||p[at+1]!=0||p[at+2]!=1)return false;int sid=p[at+3]&255,flags=(p[at+7]>>6)&3;int length=p[at+8]&255;if((flags!=2&&flags!=3)||length<5||at+9+length>188)return false;int ptsAt=at+9;long pts=readPts(p,ptsAt);if((sid&0xf0)==0xe0){video=pts;return false;}boolean audio=sid>=0xc0&&sid<=0xdf;if(!audio||video<0)return false;int pid=((p[1]&31)<<8)|(p[2]&255);Long offset=offsets.get(pid);if(offset==null){long difference=distance(pts,video);offset=Math.abs(difference)>90000L*10?difference:0L;offsets.put(pid,offset);}if(offset!=0&&Math.abs(distance((pts-offset)&MASK,video))>90000L/4){offset=distance(pts,video);offsets.put(pid,offset);}if(offset==0)return false;writePts(p,ptsAt,(pts-offset)&MASK);if(flags==3&&length>=10)writePts(p,ptsAt+5,(readPts(p,ptsAt+5)-offset)&MASK);return true;
  }
 }
 static long distance(long a,long b){long d=(a-b)&MASK;return d>WRAP/2?d-WRAP:d;}
 static long readPts(byte[] p,int a){return ((long)(p[a]&14)<<29)|((long)(p[a+1]&255)<<22)|((long)(p[a+2]&254)<<14)|((long)(p[a+3]&255)<<7)|((p[a+4]&254)>>1);}
 static void writePts(byte[] p,int a,long t){p[a]=(byte)((p[a]&0xf1)|((t>>29)&14));p[a+1]=(byte)(t>>22);p[a+2]=(byte)(((t>>14)&254)|1);p[a+3]=(byte)(t>>7);p[a+4]=(byte)(((t<<1)&254)|1);}
}
